#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;

int sum(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int product(int a, int b) {
    long long res = 1LL * a * b;
    if (res >= MOD) res %= MOD;
    return (int)res;
}

int difference(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

int pow_mod(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = product(res, base);
        base = product(base, base);
        exp >>= 1;
    }
    return res;
}

int get_bit(int x) {
    return x & (-x);
}

int n, a[10][10], ch[70010][128], id_counter=0, q_array[10][128], dp_array[10][70010];
unordered_map<bitset<128>, int> id_map;

int dfs_bitset(bitset<128> s) {
    if (id_map.count(s)) return id_map[s];
    id_map[s] = ++id_counter;
    for (int i=0; i<(1<<n); i++) {
        bitset<128> tmp = s;
        for (int j=0; j<(1<<n); j++) {
            if (!tmp[j]) {
                int x = i & j;
                while (x) {
                    int t = get_bit(x);
                    if (s[j ^ t]) {
                        tmp[j] = 1;
                        break;
                    }
                    x -= t;
                }
            }
        }
        ch[id_map[s]][i] = dfs_bitset(tmp);
    }
    return id_map[s];
}

int main() {
    scanf("%d", &n);
    dfs_bitset(1);
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            scanf("%d", &a[i][j]);
            a[i][j] = product(a[i][j], pow_mod(100, MOD - 2));
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<(1<<n); j++) {
            q_array[i][j] = 1;
            for (int k=0; k<n; k++) {
                if ((j>>k)&1) q_array[i][j] = product(q_array[i][j], a[i][k]);
                else q_array[i][j] = product(q_array[i][j], difference(1, a[i][k]));
            }
        }
    }
    dp_array[0][1] = 1;
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=id_counter; j++) {
            for (int k=0; k<(1<<n); k++) {
                dp_array[i][ch[j][k]] = sum(dp_array[i][ch[j][k]], product(dp_array[i-1][j], q_array[i-1][k]));
            }
        }
    }
    bitset<128> bits;
    for (int i=0; i<(1<<n); i++) bits[i] = 1;
    printf("%d\n", dp_array[n][id_map[bits]]);
    return 0;
}
